import type { SiteOrigins } from "../site-config";

/**
 * Regenerated by scripts/build.ts before the client bundle and the SSR bundle.
 * `release` is a 40-character git SHA, or `local` when no SHA is available.
 * It is not a secret.
 */
export const buildMeta: { release: string; builtAt: string; origins: SiteOrigins } = {
  release: "local",
  builtAt: "2026-10-04T00:00:00.000Z",
  origins: {
    indexable: false,
    deploymentOrigin: "https://crosscomm-website.vercel.app",
    publicOrigin: "https://www.crosscomm.com",
    canonicalOrigin: "https://crosscomm-website.vercel.app",
  },
};

export const buildId = buildMeta.release;
